def xy(g):
    return np.column_stack([g.geometry.x.to_numpy(), g.geometry.y.to_numpy()])

def pts(df, x="x", y="y"):
    return gpd.GeoDataFrame(df, geometry=gpd.points_from_xy(df[x], df[y]), crs=CRS)

def nearest(P_, S):
    return cKDTree(S).query(P_)[0]

def wq(v, ww, q):
    o = np.argsort(v); c = np.cumsum(ww[o]) / ww.sum()
    return float(v[o][np.searchsorted(c, q)])

def cov(S, P_, wt, r=R):
    return 100 * wt[nearest(P_, S) <= r].sum() / wt.sum()

def agree(A, B_, r=1000):
    """Share of A's stations with a B station within r."""
    return 100 * (nearest(A, B_) <= r).mean()

class Timer:
    def __init__(self, key): self.key = key
    def __enter__(self): self.t = time.time()
    def __exit__(self, *a): TIMES[self.key] = time.time() - self.t

THETA_D = {"poi": 0.35, "land": 0.30, "road": 0.20, "transit": 0.15}
THETA_POI = {"office": 0.25, "mall": 0.25, "hospital": 0.20, "hotel": 0.15, "parking": 0.15}
LAMBDA, N_TOTAL = 0.6, 1000.0

def dw_destination(df, td=THETA_D, tp=THETA_POI):
    poi = sum(tp[k] * df[f"Dm_{k}"] for k in tp)
    road = (df["Dm_art_density"] + df["Dm_int_density"] + df["Dm_art_prox"]) / 3
    return td["poi"] * poi + td["land"] * df["Dm_ci_land"] + td["road"] * road + td["transit"] * df["Dm_transit_prox"]

def dw_recompute(df, lam=LAMBDA, td=THETA_D, tp=THETA_POI, N=N_TOTAL, R_col="R"):
    Rv = df[R_col].to_numpy(float); Dv = dw_destination(df, td, tp).to_numpy(float)
    s = lam * Rv / Rv.sum() + (1 - lam) * Dv / Dv.sum()
    return N * s / s.sum()

def dw_mc(df, rng, sigma=0.30, lam_range=(0.3, 0.8), conc=50.0, R_col="R"):
    """One Monte Carlo draw: lambda ~ U, theta ~ Dirichlet, lognormal noise."""
    lam = rng.uniform(*lam_range)
    kd, kp = list(THETA_D), list(THETA_POI)
    td = dict(zip(kd, rng.dirichlet(conc * np.array([THETA_D[k] for k in kd]))))
    tp = dict(zip(kp, rng.dirichlet(conc * np.array([THETA_POI[k] for k in kp]))))
    w_ = dw_recompute(df, lam, td, tp, R_col=R_col) * rng.lognormal(0, sigma, len(df))
    return N_TOTAL * w_ / w_.sum()

def gini(x, wts):
    o = np.argsort(x); x, wts = x[o], wts[o]
    cw = np.cumsum(wts) / wts.sum(); cx = np.cumsum(x * wts) / (x * wts).sum()
    return 1 - np.sum((cx[1:] + cx[:-1]) * np.diff(cw)) - cx[0] * cw[0]

def worst_q(dist, col):
    q = dem[col]
    return min(100 * POP[(dist <= R) & (q == g).to_numpy()].sum() / POP[(q == g).to_numpy()].sum() for g in q.cat.categories)

def score(S, name, road=True):
    d = nearest(X, S)
    r = {"layout": name, "stations": len(S),
         "a_model_demand_cov": cov(S, X, w), "a_mean_dist_m": np.average(d, weights=w), "a_p95_dist_m": wq(d, w, 0.95),
         "b_population_cov": cov(S, X, POP), "b_ev_reg_cov": cov(S, X, EVR), "b_area_cov": cov(S, X, dem["area_km2"].to_numpy()),
         "b_max_dist_m": d.max(),
         "c_worst_sc_q_pop": worst_q(d, "sc_q_pop"), "c_worst_sc_q_cells": worst_q(d, "sc_q_cells"), "c_gini_dist_pop": gini(d, POP + 1e-9),
         "d_existing_all_1km": 100 * (nearest(E_ALL, S) <= 1000).mean(), "d_existing_4w_1km": 100 * (nearest(E98, S) <= 1000).mean(),
         "e_sites_500m_parking_fuel": 100 * (nearest(S, REAL) <= 500).mean()}
    if road and ROAD is not None:
        rd = ROAD.dist_to(X, S).min(axis=1)
        r.update({"f_road_mean_dist_m": np.average(np.where(np.isfinite(rd), rd, 15000), weights=w),
                  "f_road_3km_demand_cov": 100 * w[rd <= 3000].sum() / w.sum(),
                  "f_road_3km_pop_cov": 100 * POP[rd <= 3000].sum() / POP.sum(),
                  "e_sites_200m_road": 100 * (ROAD.snap(S)[1] <= 200).mean()})
    return r

